// Stage 1 verification for child 04: feeds recorded and documented payloads through dist/elicitation.js.
import { join } from "node:path";
const dist = process.argv[2];
const e = await import(join(dist, "elicitation.js"));

const cases = [
    {
        name: "app access (recorded, persist session+always)",
        params: {
            message: 'Allow Computer Use to use "Finder"?',
            requestedSchema: { properties: {}, type: "object" },
            _meta: { callId: "call_x", codex_approval_kind: "mcp_tool_call", connector_id: "computer-use", connector_name: "Computer Use", persist: ["session", "always"], riskLevel: "low", tool_name: "get_app_state", tool_params: { app: "com.apple.finder" }, tool_params_display: [{ display_name: "App", name: "app", value: "Finder" }] },
        },
    },
    {
        name: "app access persist session only (string form)",
        params: { message: "Allow Computer Use to use X?", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "mcp_tool_call", connector_id: "computer-use", persist: "session" } },
    },
    {
        name: "audio recording (approval_request, high risk)",
        params: { message: "Allow Computer Use to record computer audio?", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "mcp_tool_call", codex_request_type: "approval_request", connector_id: "computer-use", connector_name: "Computer Use", persist: ["session"], riskLevel: "high", tool_name: "start_audio_recording", tool_params: { app: "computer-audio" } } },
    },
    {
        name: "origin access (sensitive, mcp_tool_call)",
        params: { message: "Allow Browser Use to access example.com?", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "mcp_tool_call", codex_sensitive_action: true, codex_request_type: "approval_request", connector_id: "browser-use", connector_name: "Browser Use", persist: ["session", "always"], tool_params: { origin: "https://example.com" } } },
    },
    {
        name: "browsing history (message-only, not mcp_tool_call)",
        params: { message: "Allow Browser Use to read browsing history?", requestedSchema: { type: "object", properties: {} }, _meta: { connector_id: "browser-use", connector_name: "Browser Use", sensitive_data: "browsing_history" } },
    },
    {
        name: "download (persist, file_transfer)",
        params: { message: "Allow download from example.com?", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "mcp_tool_call", connector_id: "browser-use", persist: ["session"], file_transfer: "download", origin: "https://example.com" } },
    },
    {
        name: "raw CDP (high risk)",
        params: { message: "Allow full Chrome DevTools Protocol access?", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "mcp_tool_call", connector_id: "browser-use", riskLevel: "high", full_cdp_access: true } },
    },
    {
        name: "WebMCP (strict auto review + sensitive)",
        params: { message: "Allow WebMCP tool call?", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "mcp_tool_call", codex_strict_auto_review: true, codex_sensitive_action: true, connector_id: "browser-use" } },
    },
    {
        name: "email OTP",
        params: { message: "Enter the one-time code", requestedSchema: { type: "object", properties: { approved: { type: "boolean" } } }, _meta: { codex_approval_kind: "browser_email_otp", codex_requires_user_input: true, connector_id: "browser-use" } },
    },
    {
        name: "browser auth",
        params: { message: "Sign in", requestedSchema: { type: "object", properties: {} }, _meta: { codex_approval_kind: "browser_auth", codex_requires_user_input: true, connector_id: "browser-use" } },
    },
    {
        name: "url mode",
        params: { mode: "url", message: "Open this URL", url: "https://example.com", _meta: { connector_id: "browser-use" } },
    },
    {
        name: "js execution approval (node_repl, empty schema) → auto",
        params: { message: "Allow js execution?", requestedSchema: { type: "object", properties: {} }, _meta: { connector_id: "node_repl", tool_name: "js", codex_approval_kind: "mcp_tool_call", codex_strict_auto_review: true, codex_request_type: "approval_request" } },
    },
    {
        name: "js approval but sensitive → not auto",
        params: { message: "Allow js execution?", requestedSchema: { type: "object", properties: {} }, _meta: { connector_id: "node_repl", tool_name: "js", codex_approval_kind: "mcp_tool_call", codex_sensitive_action: true } },
    },
    {
        name: "form with string/boolean/enum/integer",
        params: { message: "Fill in", requestedSchema: { type: "object", properties: { name: { type: "string", title: "Name", minLength: 1 }, ok: { type: "boolean", default: true }, color: { type: "string", enum: ["r", "g"], enumNames: ["Red", "Green"] }, count: { type: "integer", minimum: 0 } }, required: ["name"] }, _meta: {} },
    },
    {
        name: "form with unsupported array field",
        params: { message: "Fill in", requestedSchema: { type: "object", properties: { items: { type: "array" } } }, _meta: {} },
    },
];
for (const { name, params } of cases) {
    const c = e.classify(params);
    const options = ["tool-approval", "message-only"].includes(c.kind) ? e.buildOptions(c).map((o) => o.label) : null;
    console.log(`\n# ${name}\n  kind=${c.kind} persist=${JSON.stringify(c.persistModes)} strict=${c.isStrictAutoReview} sensitive=${c.isSensitiveAction} userInput=${c.requiresUserInput}`);
    if (options) console.log(`  options=${JSON.stringify(options)}`);
    if (c.kind === "form") console.log(`  fields=${JSON.stringify(c.fields.map((f) => `${f.id}:${f.input.kind}${f.required ? "!" : ""}`))}`);
    if (c.declineReason) console.log(`  decline="${c.declineReason}"`);
    if (c.kind === "tool-approval" || c.kind === "message-only") console.log(`  title=${JSON.stringify(e.formatDialogTitle(c))}`);
}
console.log("\n# responses");
for (const choice of ["accept", "accept_session", "accept_always", "decline", "cancel", undefined]) console.log(`  ${choice ?? "dismissed"} → ${JSON.stringify(e.responseForChoice(choice))}`);
console.log(`  auto → ${JSON.stringify(e.AUTO_APPROVE_RESPONSE)}`);
console.log(`  decline(msg) → ${JSON.stringify(e.declineWithMessage("why"))}`);

// Drives pi in RPC mode through a scripted set of confirmation answers.
//   ANSWERS='Allow,Allow,Allow for this session,none' node confirm-driver.mjs <pi-binary> <pi args...> -- <prompt>
// Answer tokens: "Allow", "Allow for this session", "Always allow", "Deny", "Cancel", "delay:<ms>:<answer>",
// "abort" (send RPC abort while the dialog is open, like Esc), "dismiss" (cancelled: true).
import { spawn } from "node:child_process";

const argv = process.argv.slice(2);
const separator = argv.indexOf("--");
const [piBinary, ...piArgs] = argv.slice(0, separator);
const prompt = argv.slice(separator + 1).join(" ");
const answers = (process.env.ANSWERS ?? "").split(",").map((a) => a.trim()).filter(Boolean);
let answerIndex = 0;
const child = spawn(piBinary, piArgs, { stdio: ["pipe", "pipe", "pipe"] });
child.stderr.on("data", (chunk) => {
    const text = chunk.toString();
    if (!text.startsWith("Warning: No models")) process.stdout.write(`[stderr] ${text}`);
});
const send = (record) => {
    console.log(`>>> ${JSON.stringify(record).slice(0, 220)}`);
    child.stdin.write(`${JSON.stringify(record)}\n`);
};
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const t0 = Date.now();
const stamp = () => `+${((Date.now() - t0) / 1000).toFixed(1)}s`;
const handleSelect = async (record) => {
    const token = answers[answerIndex] ?? "Cancel";
    answerIndex += 1;
    console.log(`<<< ${stamp()} select #${answerIndex} title=${JSON.stringify(record.title)} options=${JSON.stringify(record.options)} → ${token}`);
    let answer = token;
    if (token.startsWith("delay:")) {
        const [, ms, real] = token.split(":");
        console.log(`    waiting ${ms} ms before answering ${real}`);
        await sleep(Number(ms));
        answer = real;
    }
    if (answer === "abort") {
        send({ type: "abort" });
        return;
    }
    if (answer === "dismiss") {
        send({ type: "extension_ui_response", id: record.id, cancelled: true });
        return;
    }
    const match = record.options.find((option) => option.startsWith(`${answer} —`) || option === answer);
    if (!match) {
        console.log(`    no option matches ${answer}; dismissing`);
        send({ type: "extension_ui_response", id: record.id, cancelled: true });
        return;
    }
    send({ type: "extension_ui_response", id: record.id, value: match });
};
let buffer = "";
child.stdout.on("data", (chunk) => {
    buffer += chunk.toString();
    let nl = buffer.indexOf("\n");
    while (nl !== -1) {
        const line = buffer.slice(0, nl).trim();
        buffer = buffer.slice(nl + 1);
        nl = buffer.indexOf("\n");
        if (!line) continue;
        let record;
        try {
            record = JSON.parse(line);
        } catch {
            console.log(`<<< (raw) ${line.slice(0, 200)}`);
            continue;
        }
        if (record.type === "extension_ui_request") {
            if (record.method === "select") void handleSelect(record);
            else if (record.method === "notify") console.log(`<<< ${stamp()} notify ${JSON.stringify(record.message).slice(0, 200)}`);
            else if (record.method === "confirm" || record.method === "input") {
                console.log(`<<< ${stamp()} ${record.method} ${JSON.stringify(record.title).slice(0, 200)} → dismiss`);
                send({ type: "extension_ui_response", id: record.id, cancelled: true });
            }
            continue;
        }
        if (record.type === "response") {
            console.log(`<<< ${stamp()} response ${JSON.stringify(record).slice(0, 160)}`);
            continue;
        }
        if (record.type === "tool_execution_start") console.log(`<<< ${stamp()} tool start ${record.toolName} ${JSON.stringify(record.args?.code ?? "").slice(0, 120)}`);
        else if (record.type === "tool_execution_end") console.log(`<<< ${stamp()} tool end isError=${record.isError} ${JSON.stringify(record.result?.content?.map((b) => (b.type === "text" ? b.text.slice(0, 160) : b.type)) ?? "")}`);
        else if (record.type === "agent_end") {
            console.log(`<<< ${stamp()} agent_end`);
            setTimeout(() => child.kill("SIGTERM"), Number(process.env.LINGER_MS ?? 3000));
        } else if (record.type === "message_end" && record.message?.role === "assistant") {
            const text = (record.message.content ?? []).filter((c) => c.type === "text").map((c) => c.text).join(" ");
            if (text) console.log(`<<< ${stamp()} assistant: ${text.slice(0, 400)}`);
        }
    }
});
child.on("exit", (code, signal) => console.log(`pi exited code=${code} signal=${signal}`));
setTimeout(() => send({ id: "p1", type: "prompt", message: prompt }), 1500);
setTimeout(() => {
    console.log("timeout: killing pi");
    child.kill("SIGKILL");
}, Number(process.env.MAX_MS ?? 400_000)).unref();
